// function would make the whole predicate opaque to the planner, which is the
// one thing this design cannot afford — see `plan_cache_mode` in pool.go. The
// SQL source test in discover_sql_test.go is what keeps the copies identical:
// it reads THIS file and fails when a query drops a clause.
//
// Nothing here concatenates SQL and nothing interpolates a JSONPath. The
// attribute filter (Task 22) is absent for that reason and lands as a bound
// `@?` parameter when it arrives, never as text spliced into these queries.
// ---------------------------------------------------------------------------
// retrieval — one query per ranked mode, all sharing one WHERE
// ---------------------------------------------------------------------------
// LexicalCandidates ranks by full-text relevance.
//
// `discover_tsquery` ORs its terms (Migration 005), so this is a BROAD
// retriever by design: "wheat seeds for sale" matches every listing carrying
// any one of those words and ts_rank_cd floats the ones matching more. Recall
// is the retriever's job and precision is RRF's. That is also why the LIMIT is
// not optional — without it a two-word query returns the corpus.
//
// A NULL `query_text` matches every row the shared predicates admit rather than
// none. An intent may carry only a spatial constraint, and a retriever that
// returned nothing for it would make a geo-only discover answer empty; with no
// text there is no relevance, so the ORDER BY falls through to the stable key.
func (q *Queries) LexicalCandidates(ctx context.Context, arg LexicalCandidatesParams) ([]LexicalCandidatesRow, error) {
	rows, err := q.db.Query(ctx, lexicalCandidates,
		arg.NetworkID,
		arg.SchemaContexts,
		arg.SchemaTypes,
		arg.SpatialOp,
		arg.GeoNegate,
		arg.TargetPaths,
		arg.MatchNegate,
		arg.MinLat,
		arg.MaxLat,
		arg.MinLon,
		arg.MaxLon,
		arg.QCover,
		arg.QFull,
		arg.CenterLat,
		arg.CenterLon,
		arg.RadiusM,
		arg.QueryText,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []LexicalCandidatesRow{}
	for rows.Next() {
		var i LexicalCandidatesRow
		if err := rows.Scan(&i.CatalogID, &i.ID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const scopeFilterResources = `-- name: ScopeFilterResources :many

SELECT r.catalog_id, r.id
  FROM resources r
  JOIN (SELECT c.v AS catalog_id, i.v AS resource_id
          FROM unnest($1::text[])  WITH ORDINALITY AS c(v, n)
          JOIN unnest($2::text[]) WITH ORDINALITY AS i(v, n) USING (n)) AS p
    ON r.catalog_id = p.catalog_id AND r.id = p.resource_id
 WHERE ($3::text IS NULL
        OR r.visible_to @> ARRAY[$3::text])
   AND r.active
   AND (r.valid_from IS NULL OR r.valid_from <= now())
   AND (r.valid_to   IS NULL OR r.valid_to   >= now())
   AND within_daily_window(r.valid_time_from, r.valid_time_to,
                           (now() AT TIME ZONE 'UTC')::time)
`

type ScopeFilterResourcesParams struct {
	CatalogIds  []string
	ResourceIds []string
	NetworkID   pgtype.Text
}

type ScopeFilterResourcesRow struct {
	CatalogID string
	ID        string
}

// ---------------------------------------------------------------------------
// hydration — three queries, all keyed by the decided page
// ---------------------------------------------------------------------------
// ScopeFilterResources narrows a set of ids to the ones the scope admits.
//
// It exists for retrievers that come from an index with no notion of validity
// or visibility — a vector index is one — and it is the gate and nothing else:
// no text, no geometry, no schema, because the caller has already applied those
// and this answers only "may this caller see it now".
func (q *Queries) ScopeFilterResources(ctx context.Context, arg ScopeFilterResourcesParams) ([]ScopeFilterResourcesRow, error) {
	rows, err := q.db.Query(ctx, scopeFilterResources, arg.CatalogIds, arg.ResourceIds, arg.NetworkID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ScopeFilterResourcesRow{}
	for rows.Next() {
		var i ScopeFilterResourcesRow
		if err := rows.Scan(&i.CatalogID, &i.ID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const semanticCandidates = `-- name: SemanticCandidates :many
SELECT r.catalog_id, r.id
  FROM resources r
 WHERE ($1::text IS NULL
        OR r.visible_to @> ARRAY[$1::text])
   AND r.active
   AND (r.valid_from IS NULL OR r.valid_from <= now())
   AND (r.valid_to   IS NULL OR r.valid_to   >= now())
   AND within_daily_window(r.valid_time_from, r.valid_time_to,
                           (now() AT TIME ZONE 'UTC')::time)
   AND (   $2::text[] IS NULL
        OR cardinality($2::text[]) = 0
        OR (    r.schema_context = ANY($2::text[])
            AND EXISTS (SELECT 1
                          FROM unnest($2::text[])
                                 WITH ORDINALITY AS sc(ctx, n)
                          JOIN unnest($3::text[])
                                 WITH ORDINALITY AS st(typ, n) USING (n)
                         WHERE r.schema_context = sc.ctx
                           AND (st.typ = '' OR r.schema_type = st.typ))))
   AND (
     $4::text IS NULL
     OR $5::boolean <> EXISTS (
       SELECT 1 FROM resource_geometries g
        WHERE g.catalog_id = r.catalog_id
          AND (g.resource_id IS NULL OR g.resource_id = r.id)
          AND ($6::text[] IS NULL
               OR g.target_path = ANY($6::text[]))
          AND $7::boolean <> (
                 ($8::double precision IS NULL
                  OR $4::text = 'S_DISJOINT'
                  OR (    g.max_lat >= $8::double precision
                      AND g.min_lat <= $9::double precision
                      AND g.max_lon >= $10::double precision
                      AND g.min_lon <= $11::double precision))
                 AND (g.cells_cover IS NULL
                      OR $12::bigint[] IS NULL
                      OR CASE $4::text
                           WHEN 'S_INTERSECTS' THEN g.cells_cover && $12::bigint[]
                           WHEN 'S_DISJOINT'   THEN NOT (g.cells_full && $13::bigint[])
                                               AND NOT (g.cells_cover <@ $13::bigint[])
                                               AND NOT ($12::bigint[] <@ g.cells_full)
                           WHEN 'S_WITHIN'     THEN g.cells_cover <@ $12::bigint[]
                           WHEN 'S_CONTAINS'   THEN $12::bigint[] <@ g.cells_cover
                           WHEN 'S_DWITHIN'    THEN g.cells_cover && $12::bigint[]
                           WHEN 'S_OVERLAPS'   THEN g.cells_cover && $12::bigint[]
                                               AND NOT (g.cells_cover <@ $13::bigint[])
                                               AND NOT ($12::bigint[] <@ g.cells_full)
                           WHEN 'S_EQUALS'     THEN g.cells_cover = $12::bigint[]
                                               AND g.cells_full  = $13::bigint[]
                           ELSE TRUE
                         END)
                 AND ($14::double precision IS NULL
                      OR g.geojson->>'type' <> 'Point'
                      OR geo_distance_m(g.geojson,
                                        $14::double precision,
                                        $15::double precision)
                          <= $16::double precision))
     )
   )
   AND $17::vector IS NOT NULL
   AND r.embedding IS NOT NULL
 ORDER BY r.embedding <=> $17::vector,
          r.catalog_id, r.id
 LIMIT $18::int
`

type SemanticCandidatesParams struct {
	NetworkID      pgtype.Text
	SchemaContexts []string
	SchemaTypes    []string
	SpatialOp      pgtype.Text
	GeoNegate      bool
	TargetPaths    []string
	MatchNegate    bool
	MinLat         pgtype.Float8
	MaxLat         pgtype.Float8
	MinLon         pgtype.Float8
	MaxLon         pgtype.Float8
	QCover         []int64
	QFull          []int64
	CenterLat      pgtype.Float8
	CenterLon      pgtype.Float8
	RadiusM        pgtype.Float8
	QueryVector    *pgvector_go.Vector
	RowLimit       int32
}

type SemanticCandidatesRow struct {
	CatalogID string
	ID        string
}

// SemanticCandidates ranks by cosine distance over the HNSW index.
//
// `embedding IS NOT NULL` is not defensive: in Phase 1 EMBEDDING_PROVIDER is
// noop and EVERY row is NULL (A5), so this mode returns nothing at all and the
// fusion is lexical + fuzzy. It is written and exercised anyway — `make test`
// pins EMBEDDING_PROVIDER=hashing for exactly that reason — because the day the
// provider changes is not the day to discover this query does not compile.
//
// The ORDER BY is what drives the index; there is no distance threshold,
// because HNSW answers "the nearest N" and not "everything within d". The pool
// this draws from is every embedded row the shared predicates admit, which is
// what CountCandidates counts for this mode.
func (q *Queries) SemanticCandidates(ctx context.Context, arg SemanticCandidatesParams) ([]SemanticCandidatesRow, error) {
	rows, err := q.db.Query(ctx, semanticCandidates,
		arg.NetworkID,
		arg.SchemaContexts,
		arg.SchemaTypes,
		arg.SpatialOp,
		arg.GeoNegate,
		arg.TargetPaths,
		arg.MatchNegate,
		arg.MinLat,
		arg.MaxLat,
		arg.MinLon,
		arg.MaxLon,
		arg.QCover,
		arg.QFull,
		arg.CenterLat,
		arg.CenterLon,
		arg.RadiusM,
		arg.QueryVector,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SemanticCandidatesRow{}
	for rows.Next() {
		var i SemanticCandidatesRow
		if err := rows.Scan(&i.CatalogID, &i.ID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
